import React from 'react';
import { Code2, Heart, ArrowUp } from 'lucide-react';

const Footer = () => {
  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const quickLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Services', href: '#services' },
    { name: 'Portfolio', href: '#portfolio' },
    { name: 'Contact', href: '#contact' }
  ];

  const services = [
    'Web Development',
    'UI/UX Design',
    'System Development',
    'E-Commerce',
    'Maintenance'
  ];

  return (
    <footer className="bg-[#0a1628] border-t border-white/5">
      {/* Main Footer */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12">
          {/* Brand */}
          <div className="lg:col-span-1">
            <a href="#home" className="flex items-center gap-2 mb-6">
              <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center">
                <Code2 className="w-6 h-6 text-white" />
              </div>
              <span className="text-xl font-bold text-white">
                Project <span className="gradient-text">MUN</span>
              </span>
            </a>
            <p className="text-gray-400 text-sm leading-relaxed mb-6">
              A passionate web development team dedicated to creating innovative 
              digital solutions for modern businesses.
            </p>
            {/* Back to top */}
            <button
              onClick={scrollToTop}
              className="flex items-center gap-2 text-gray-400 hover:text-white transition-colors group"
            >
              <span className="text-sm">Back to top</span>
              <div className="w-8 h-8 rounded-full glass flex items-center justify-center group-hover:bg-blue-500/20 transition-colors">
                <ArrowUp className="w-4 h-4" />
              </div>
            </button>
          </div>

          {/* Quick Links */}
          <div>
            <h4 className="text-white font-semibold mb-6">Quick Links</h4>
            <ul className="space-y-3">
              {quickLinks.map((link) => (
                <li key={link.name}>
                  <a
                    href={link.href}
                    className="text-gray-400 hover:text-white transition-colors text-sm"
                  >
                    {link.name}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          {/* Services */}
          <div>
            <h4 className="text-white font-semibold mb-6">Services</h4>
            <ul className="space-y-3">
              {services.map((service) => (
                <li key={service}>
                  <span className="text-gray-400 text-sm">{service}</span>
                </li>
              ))}
            </ul>
          </div>

          {/* Team Credits */}
          <div>
            <h4 className="text-white font-semibold mb-6">Team</h4>
            <ul className="space-y-3">
              {[
                { name: 'Ruben Albao', role: 'Project Lead' },
                { name: 'Kristian Gomez', role: 'Frontend Dev' },
                { name: 'Jonelle Mayari', role: 'UI/UX Designer' },
                { name: 'Alvin Panganiban', role: 'Full Stack Dev' }
              ].map((member) => (
                <li key={member.name} className="text-sm">
                  <span className="text-white">{member.name}</span>
                  <span className="text-gray-500 block text-xs">{member.role}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      {/* Bottom Bar */}
      <div className="border-t border-white/5">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <p className="text-gray-400 text-sm text-center sm:text-left">
              &copy; {new Date().getFullYear()} Project MUN. All rights reserved.
            </p>
            <p className="text-gray-500 text-sm flex items-center gap-1">
              Made with <Heart className="w-4 h-4 text-red-500 fill-red-500" /> by Project MUN Team
            </p>
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
